gU1(){return"\u0416\u043e\u049b. \u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0442\u043e\u049b\u0442\u0430\u0443\u0493\u0430 \u0434\u0430, \u0442\u04b1\u0440\u0430\u049b\u049b\u0430 \u0434\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b."},
gU4(){return"\u0416\u043e\u043b\u0430\u0443\u0448\u044b\u043d\u044b \u0442\u04af\u0441\u0456\u0440\u0443 \u04af\u0448\u0456\u043d \u0442\u043e\u049b\u0442\u0430\u0439 \u0430\u043b\u0430\u043c\u044b\u043d \u0431\u0430?"},
gU3(){return"\u0418\u04d9. \u0411\u0435\u043b\u0433\u0456 \u0442\u04b1\u0440\u0430\u049b\u049b\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b, \u0431\u0456\u0440\u0430\u049b \u0442\u043e\u049b\u0442\u0430\u0442\u0443\u0493\u0430 \u043c\u04af\u043c\u043a\u0456\u043d\u0434\u0456\u043a \u0431\u0435\u0440\u0435\u0434\u0456. \u041e\u0442\u044b\u0440\u0493\u044b\u0437\u0443, \u0442\u04af\u0441\u0456\u0440\u0443 \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u0438\u0435\u0443 \u04af\u0448\u0456\u043d \u049b\u0430\u0436\u0435\u0442\u0442\u0456 \u0443\u0430\u049b\u044b\u0442 5 \u043c\u0438\u043d\u0443\u0442\u0442\u0430\u043d \u0430\u0441\u0443\u044b \u043c\u04af\u043c\u043a\u0456\u043d."},
gU6(){return"\u041a\u04d9\u0434\u0456\u043c\u0433\u0456 \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 20 \u043c\u0438\u043d\u0443\u0442\u049b\u0430 \u049b\u043e\u043d\u0434\u044b\u0440\u043c\u0430\u0439 \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u0438\u0435\u0443\u0441\u0456\u0437 \u049b\u0430\u043b\u0434\u044b\u0440\u0430 \u0430\u043b\u0430\u043c\u044b\u043d \u0431\u0430?"},
