gUc(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0436\u043e\u043b\u0430\u0443\u0448\u044b\u043d\u044b \u0430\u043b\u044b\u043f \u043a\u0435\u0442\u0443 \u04af\u0448\u0456\u043d 3 \u043c\u0438\u043d\u0443\u0442 \u0442\u043e\u049b\u0442\u0430\u0443\u0493\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430 \u043c\u0430?"},
