gUR(){return"\u0416\u043e\u049b. \u041e\u043b\u0430\u0440 \u0442\u0435\u043a \u043a\u04e9\u0440\u0441\u0435\u0442\u043a\u0456\u043b\u0435\u0440\u043c\u0435\u043d \u043a\u04e9\u0440\u0441\u0435\u0442\u0456\u043b\u0433\u0435\u043d \u0431\u0430\u0493\u044b\u0442\u0442\u0430 \u0448\u0435\u04a3\u0431\u0435\u0440 \u0431\u043e\u0439\u044b\u043c\u0435\u043d \u049b\u043e\u0437\u0493\u0430\u043b\u0430\u0434\u044b."},
