gVb(){return"\u0422\u0456\u0440\u043a\u0435\u043c\u0435\u0441\u0456\u0437 \u0436\u0435\u04a3\u0456\u043b \u0430\u0432\u0442\u043e\u043a\u04e9\u043b\u0456\u043a: \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u044c \u0436\u043e\u043b\u044b\u043d\u0434\u0430\u0493\u044b \u0436\u0430\u043b\u043f\u044b \u0448\u0435\u043a 110 \u043a\u043c/\u0441\u0430\u0493?"},
gVa(){return"\u0418\u04d9. \u0422\u0456\u0440\u043a\u0435\u043c\u0435\u0441\u0456 \u0436\u043e\u049b \u0436\u0435\u04a3\u0456\u043b \u0430\u0432\u0442\u043e\u043a\u04e9\u043b\u0456\u043a\u0442\u0456\u04a3 \u0436\u0430\u043b\u043f\u044b \u0448\u0435\u0433\u0456 110 \u043a\u043c/\u0441\u0430\u0493. \u0411\u0435\u043b\u0433\u0456\u043b\u0435\u0440 \u0431\u0430\u0441\u049b\u0430 \u0448\u0435\u043a\u0442\u0456 \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u0443\u0456 \u043c\u04af\u043c\u043a\u0456\u043d (10.3-\u0442\u0430\u0440\u043c\u0430\u049b)."},
